            ]
          }
        },
        "/v2/pings": {
          "get": {
            "summary": "Transitional GPS pings (deprecated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/positions": {
          "get": {
            "summary": "Canonical current vehicle positions",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v1/journeys": {
          "get": {
            "summary": "Legacy journeys (deprecated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/routes": {
          "get": {
            "summary": "Route planning resource (NOT trip history)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
